//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::float::to_uint64`; the
//! native twin is `benches/native/Bench/FloatToUint64.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::float;
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(float::to_uint64(
            (-2e+19 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 4e+19),
        ) as u64);
    }
    acc as u64
}

fn main() {
    run(|| (), kernel)
}
